    --input: 217.2 32.6% 17.5%;
    --ring: 212.7 26.8% 83.9%;

    /* App theme variables (dark) */
    --app-bg: #000000;
    --app-surface: rgb(17,17,17);
    --app-surface-border: rgb(20,20,20);
    --app-surface-hover: rgb(34,34,34);
    --app-border: #141414;
