  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* SuperDoc Editor Styles - Matching the text-editor sample UI */
.superdoc-toolbar {
  background: var(--app-surface);
  border-bottom: 1px solid var(--app-surface-border);
  color: var(--app-text-primary);
  min-height: 44px;
}

.superdoc-editor-host {
  background: #ffffff;
  color: #111111;
  overflow: hidden;
}

.dark .superdoc-editor-host {
  background: #ffffff;
  color: #111111;
}

.superdoc-editor-host h1,
.superdoc-editor-host h2,
.superdoc-editor-host h3 {
  font-family: 'Urbanist', sans-serif;
}

.superdoc-editor-host p,
.superdoc-editor-host li {
  font-family: 'Geist Mono', Menlo, Monaco, Consolas, monospace;
}

/* Velt comment highlighting */
velt-comment-text {
  background-color: rgba(255, 212, 0, 0.4) !important;
  border-bottom: 2px solid #ffd400 !important;
  cursor: pointer !important;
}

velt-comment-text:hover,
velt-comment-text[comment-selected="true"],
velt-comment-text.velt-comment-selected {
  background-color: rgba(255, 212, 0, 0.7) !important;
}

/* Helper Text Animation */
@keyframes pulse-subtle {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.animate-pulse-subtle {
  animation: pulse-subtle 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

/* Collaboration cursor styling - Dark theme adjustments */
.collaboration-cursor__caret {
  border-left: 1px solid #ffffff;
  border-right: 1px solid #ffffff;
  margin-left: -1px;
  margin-right: -1px;
  pointer-events: none;
  position: relative;
  word-break: normal;
}

/* Render the username above the caret */
.collaboration-cursor__label {
  border-radius: 3px 3px 3px 0;
  color: #000000;
  background: #ffffff;
  font-size: 12px;
  font-style: normal;
  font-weight: 600;
  left: -1px;
  line-height: normal;
  padding: 0.1rem 0.3rem;
  position: absolute;
  top: -1.4em;
  user-select: none;
  white-space: nowrap;
}

nextConfigContent:
/** @type {import('next').NextConfig} */
const path = require('path');

// List of domains allowed to embed this app in an iframe
const allowList = [
  "'self'",
  "http://localhost:*",
  "https://*.vercel.app",
  "https://*.velt.dev",
  "https://*.mintlify.app",
].join(' ');

const EMBED_CSP = `frame-ancestors ${allowList}`;

const nextConfig = {
  reactStrictMode: false,
  turbopack: {
    root: path.join(__dirname, '..', '..', '..', '..', '..', '..'),
  },
  async headers() {
    return [
      {
        source: '/:path*',
        headers: [
          {
            key: 'Content-Security-Policy',
            value: EMBED_CSP,
          },
        ],
      },
    ]
  },
}

module.exports = nextConfig
